\begin{lemma}[Induction from coordinate sectors]\label{lem:sector-induction}
Let a finite group $G$ act transitively on a finite set $\Omega$.
Suppose a $G$-module has a direct-sum decomposition
$T=\bigoplus_{A\in\Omega}T_A$ with $gT_A=T_{gA}$.
Fix $D\in\Omega$, let $H$ be its stabilizer, and take $z\in T_D$.
If $A_0=\C[H]z$, then the map
\begin{equation}\label{band:induced-map}
 \Phi:\C[G]\otimes_{\C[H]}A_0\longrightarrow\C[G]z,
 \qquad g\otimes a\longmapsto ga
\end{equation}
is an isomorphism of $G$-modules.
\end{lemma}

\begin{proposition}[Band quotient]\label{prop:band-quotient}
For the parameters in \Cref{band:sets}, there is a surjective
$G_m$-equivariant map
\begin{equation}\label{band:quotient}
 W_m\twoheadrightarrow
 \Ind_{S_D\times S_F}^{S_{B_m}}(W_h\boxtimes U_{m,s}).
\end{equation}
In particular, every irreducible constituent of the induced module on
the right is a constituent of $W_m$.
\end{proposition}

\begin{theorem}[Cyclic staircase support]
\label{thm:cyclic-saxl}
For every $m\ge1$ and every partition $\lambda\vdash N_m$, the irreducible
$S^\lambda$ occurs in $W_m$.
\end{theorem}

\begin{proposition}
\label{prop:dominated}
If $m\ge1$, $\lambda\vdash N_m$, and $\rho_m\unrhd\lambda$, then
$S^\lambda$ occurs in $W_m$.
\end{proposition}

\begin{lemma}[Path contraction]\label{path:contraction}
For arbitrary $X_1,\ldots,X_K\in\Mat_2(\C)$,
\begin{equation}\label{path:contraction-formula}
 \left\langle u,X_1\otimes\cdots\otimes X_K\right\rangle
 =(-1)^{m-1}
 \left[X_1\adj(X_2)X_3\adj(X_4)\cdots
                 X_{K-2}\adj(X_{K-1})X_K\right]_{11}.
\end{equation}
\end{lemma}

\begin{lemma}[Segment alternation]\label{path:segment}
Let $e$ be the number of even positions among $p,\ldots,p+r-1$, and put
$\delta=1$ if $p$ is even and $\delta=0$ otherwise. Then
\begin{equation}\label{path:segment-formula}
 A_{r,p}=r!(-1)^{e-\delta}M_1\cdots M_r.
\end{equation}
In particular, all these matrices are invertible. Their values are
\begin{equation}\label{path:segment-table}
 \begin{array}{c|cc}
 r & p\text{ odd} & p\text{ even}\\ \hline
 1&I&I\\
 2&-2Z&2Z\\
 3&-6J&-6J\\
 4&-24I&24I
 \end{array}
\end{equation}
\end{lemma}

\begin{proposition}[Four-row support of the width-two band]\label{prop:two-band}
For every $m\geq3$ and every partition $\eta\vdash 2m-1$ with
$\len(\eta)\leq4$, the irreducible module $S^\eta$ occurs in $U_{m,2}$.
\end{proposition}

\begin{lemma}[Alternating blocks as polytabloids]\label{lem:polytabloid}
Define $\theta_i=\#\{A\in L:|A|\ge i\}$, so that the block sizes are
the column lengths of $\theta$.  Then
$\C[S_B]v_L\cong S^\theta$.
The same assertion holds for any ordered basis of a dual vector space.
\end{lemma}

\begin{lemma}[Pieri rule]\label{lem:pieri}
For $\nu\vdash a$ and $b\ge0$,
\begin{equation}\label{tools:pieri}
 \Ind_{S_a\times S_b}^{S_{a+b}}
      (S^\nu\boxtimes\mathbf1)
 \cong
 \bigoplus_{\substack{\lambda\vdash a+b,\ \lambda\supseteq\nu\\
                      \lambda/\nu\text{ a horizontal strip}}}
       S^\lambda.
\end{equation}
Every summand occurs once.
\end{lemma}

\begin{lemma}[Compressed-block trial]
\label{lem:compressed}
For sufficiently large main-branch inputs, the compressed-block trial
uses at most $u^{15}2^{n/2}$ word operations on every random outcome,
including bounded sampling, and uses
$O(u(C+1)+B+2^s+2^{.14n})$ writable words. Every returned YES is
correct. If the input is a YES instance and
\begin{equation}
\label{alg:high-deficiency}
 \mu\ge .00765n,
\end{equation}
its success probability is bounded below by an absolute positive
constant.
\end{lemma}

\begin{corollary}
\label{cor:target}
For every fixed $\rho>0.199$, the same algorithm has ordinary
$O_{c,\rho}(2^{\rho n})$ word space under each fixed polynomial-bit
convention, with the time and correctness guarantees of
Theorem~\ref{thm:main}. In particular, it has
$O_c(2^{n/5})$ word space.
\end{corollary}

\begin{lemma}[Deficiency]
\label{lem:deficiency}
For arbitrary fixed weights on the $n$ indices, deficiency is
nonnegative, invariant under sign changes of individual weights,
inclusion-monotone, and superadditive on disjoint domains. Replacing
one index in a domain of fixed size changes its deficiency by at most
one. If $V$ is uniform among the size-$v$ domains, $0\le v\le n$,
then
\begin{equation}
\label{eq:deficiency-variance}
 \operatorname{Var}(\defect(V))\le v.
\end{equation}
\end{lemma}

\begin{lemma}[Elementary entropy bounds]
\label{lem:entropy}
For integers $0\le k\le v$,
\[
 \frac{2^{v h(k/v)}}{v+1}\le \binom vk\le 2^{v h(k/v)}.
\]
For $v=k=0$, interpret $v h(k/v)$ as zero. Entropy is concave,
symmetric about $1/2$, and increasing on $[0,1/2]$. Moreover,
\begin{equation}
\label{eq:entropy-numbers}
 h_*<.8114,\qquad h(1/3)<14/15,\qquad h(1/6)>5/8.
\end{equation}
\end{lemma}

\begin{lemma}\label{alg:validity}
Every retained parent entry has a subset witness on its parent's
indices.  Deduplicating entries by actual weight and top mask preserves
the existence of every valid final match.  Every YES returned by either
trial is correct.
\end{lemma}

\begin{lemma}\label{lem:resources}
On a YES input with \(\mu<.00765n\), a representation trial with
the bounded samplers and operation cap succeeds with probability at
least \(u^{-110}\), for sufficiently large main-branch inputs.
\end{lemma}

\begin{lemma}\label{lem:representation}
For a main-branch YES input with \(\mu<.00765n\), ideal sampling
produces, with probability at least \(u^{-100}\), a passing spread test and a representation of a solution satisfying all prescribed leaf
counts and all low modular filters. Its two parent weights
\(x_L,x_R\), with \(x_L+x_R=t'\), and all of its masks can be fixed as
functions of the nonfamily choices preceding \(q\). Conditional on
these choices, \(q\) still has its prescribed independent prime law;
the separating families also retain their prescribed product law,
with the now fixed layout parameters.
\end{lemma}

\begin{theorem}[Classification]\label{thm:classification}
Let $A=\{a_1,\ldots,a_s\}\subset\R^d$ be a finite set of at least two
points with affine span $\R^d$, and define $p_i,F,B,m_F$ as above.
Then $A$ is Ramsey if and only if there is a matrix
$P\in\operatorname{Mat}_{d+1}(B)$ such that
\begin{align}
 (p_i\otimes1)^T P(1\otimes p_i)&=0
       &&(1\le i\le s),\label{eq:field-evaluations}\\
 m_F(P_{\alpha\beta})&=\delta_{\alpha\beta}
       &&(1\le\alpha,\beta\le d).\label{eq:field-spatial}
\end{align}
Here the entries of $p_i\otimes1$ and $1\otimes p_i$ are formed
componentwise. There are no separate conditions on the multiplied
constant row or constant column of $P$.
\end{theorem}

\begin{proposition}\label{alg:equivalence}
The matrix condition in Theorem~\ref{thm:classification} is equivalent
to~\eqref{alg:tensor}.
\end{proposition}

\begin{proposition}\label{alg:necessity}
If~\eqref{alg:tensor} has no solution, then there is an integer $r_0\geq2$
such that every $\R^D$ admits an $r_0$-coloring with no monochromatic
congruent copy of $A$.  In particular, every Euclidean Ramsey set
satisfies the matrix condition of Theorem~\ref{thm:classification}.
\end{proposition}

\begin{lemma}[A compactly supported smoothing function]\label{pairs:bump}
Let $C$ be a real symmetric $k\times k$ matrix and let
$U\in\operatorname{Mat}_{d\times k}(\R)$, where $d\geq1$ and
$UCU^{\mathsf T}=I_d$. For every $\eta>0$, there is a nonnegative
$b\in C_c^\infty(\R^k)$ such that
\begin{equation}\label{pairs:bump-bound}
 \int_{\R^k}b(x)\,dx>0,
 \qquad
 \int_{\R^k}(D_Cb)_-(x)\|Ux\|^2\,dx
 <\eta\int_{\R^k}b(x)\,dx.
\end{equation}
\end{lemma}

\begin{proposition}[A path criterion]\label{paths:criterion}
Suppose that for every integer $n\ge1$ there are two paths with the
same endpoint and weights $\lambda>0$ and $\mu\ge0$ satisfying
$\mu/\lambda<1/n$. Then $A$ is Euclidean Ramsey.
\end{proposition}

\begin{lemma}\label{paths:compactness}
Fix an integer $r\ge2$. If every $r$-coloring of $\mathcal E$ contains
a monochromatic congruent copy of $A$, then the same holds for every
$r$-coloring of $\R^D$, for some finite $D$.
\end{lemma}

\begin{lemma}\label{paths:synchronization}
Fix an integer $n\ge1$. Let two paths have the same endpoint and weights $\lambda>0$ and
$\mu\ge0$. If $\rho=\mu/\lambda<1/n$, then there is an endpoint
$w\in K^s$ admitting a path of weight $1/t$ for every integer
$1\le t\le n$.
\end{lemma}

\begin{lemma}\label{paths:corner-group}
The operation in \eqref{paths:ultrafilter-product} makes
$\beta\mathcal S$ a compact right-topological semigroup with identity
$\delta_\epsilon$. It contains an idempotent $p$ such that
$p(\beta\mathcal S)p$ is a group with identity $p$.
\end{lemma}

\begin{lemma}[Simultaneous realization]\label{paths:realization}
Let $q_{i,j}\in\beta\mathcal S$ for $1\le i\le s$ and
$1\le j\le M$, where $M\ge1$. Suppose that every column $j$ has
one of the following specified forms:
\begin{enumerate}
\item $q_{i,j}=q_j$ is independent of $i$;
\item $q_{i,j}=\delta_{z_{i,j}}$ for prescribed strings
      $z_{i,j}\in\mathcal S$.
\end{enumerate}
If $B\in q_{i,1}\cdots q_{i,M}$ for every $i$, there are strings
$x_{i,j}$ such that all products $x_{i,1}\cdots x_{i,M}$ belong to
$B$, with $x_{i,j}$ independent of $i$ in each column of the first
form and $x_{i,j}=z_{i,j}$ in each column of the second form.
\end{lemma}

\begin{lemma}\label{groups:pairs}
For every $i\ne j$, the monoid $M_{ij}$ is a group containing
$N\times N$.
\end{lemma}

\begin{lemma}\label{groups:averaging}
Let $H$ be a finite group of coordinate permutations of $\mathcal E$,
and let $Z\subset\mathcal E$ be a finite $H$-invariant set. For every
$\delta>0$, there is a tuple $w\in K^Z$ represented by diagonal
factors and factors $(\xi_{h x})_{x\in Z}$, $h\in H$, with degree
$m>0$, for which
\begin{equation}\label{groups:orbit-bound}
 w_xw_y^{-1}\in L,\qquad c(w_xw_y^{-1})\le\delta m
 \quad\text{whenever }x,y\text{ belong to the same }H\text{-orbit}.
\end{equation}
\end{lemma}

\begin{corollary}\label{cons:spherical}
Every finite Euclidean Ramsey set is spherical.
\end{corollary}

\begin{corollary}\label{cons:transitive}
Every nonempty subset of a finite transitive Euclidean set is Ramsey.
\end{corollary}

\begin{proposition}\label{cons:quadratic}
Let $A=\{a_1,\ldots,a_s\}\subset\R^d$ be spherical and affinely
span $\R^d$. Put $p_i=(1,a_i)^{\mathsf T}$ and let $F$ be its
coordinate field. If the $s$ row vectors
\[
 (p_{i\alpha}p_{i\beta})_{0\le\alpha,\beta\le d}
 \quad(1\le i\le s)
\]
are linearly independent over $F$, then $A$ is Ramsey.
\end{proposition}

\begin{corollary}\label{cons:quadrilateral}
Every nonempty set of at most five distinct points on a circle is Ramsey.
In particular, every cyclic quadrilateral is Ramsey.
\end{corollary}

\begin{corollary}\label{cons:kites}
For every transcendental $a\in(-1,1)$, the cyclic quadrilateral
\[
 K_a=\bigl\{(-1,0),(1,0),
             (a,\sqrt{1-a^2}),(a,-\sqrt{1-a^2})\bigr\}
\]
is Ramsey and is not subtransitive.
\end{corollary}

\begin{lemma}[Sparse distinctions]
\label{lem:sparse-distinction}
With probability $1-o(1)$ over $P$, the following implication holds
simultaneously for every $v\in\{-1,0,1\}^n$ with at most $m$ nonzero
coordinates:
\begin{equation}
 \sum_i v_ic_i\ne0
 \quad\Longrightarrow\quad
 \sum_i v_ic_i\not\equiv0\pmod P.
 \label{eq:sparse-distinction}
\end{equation}
The error is uniform under \eqref{eq:bit-guard}.
\end{lemma}

\begin{lemma}[Coverage and sizes]
\label{lemma:checksum-tables}
For the preceding random construction, the following statements hold.
\begin{enumerate}[label=\textup{(\roman*)}]
\item Conditional on arbitrary phases, the probability that some
$k<P$ has no match in its own pattern is $o(1)$, uniformly in the
phases and residues.
\item In each fixed pattern, the expected number of entries on either
side is at most $2^{(\tau+8\eps)n+O(\sqrt n)}$, and
\begin{equation}
 \E L_\pi\le
 2^{(\eta-\alpha U_\pi+12\eps)n+O(\sqrt n)}.
 \label{eq:checksum-match-expectation}
\end{equation}
The entry estimates hold conditional on the phases.  The match
estimate averages over both phases and tables.
\item With probability $1-o(1)$, all frequencies are covered in their
own patterns and, in every pattern, both entry counts are at most
$2^{(\tau+14\eps)n}$ and
\begin{equation}
 L_\pi\le2^{(\eta-\alpha U_\pi+18\eps)n}.
 \label{eq:checksum-match-good}
\end{equation}
\end{enumerate}
\end{lemma}

\begin{proposition}[Filtering moments]\label{prop:filtering-moments}
The functions in \eqref{eq:filter-scores} satisfy
\begin{equation}\label{eq:continuous-filtering-moments}
\begin{split}
 \int_{\mathbb T}M(x)^2 2^{8.5(\Delta-u(x))}\,dx&<2^{0.5168},\\
 \int_{\mathbb T}M(x)^2 2^{8.3(a v(x)-u(x))}\,dx&<2^{0.5168}.
\end{split}
\end{equation}
\end{proposition}

\begin{lemma}[Finite filtering data]\label{lemma:finite-filtering}\label{filtering-finite}
There is an absolute integer $P_0$ such that for every $P\ge P_0$ the
finite functions satisfy \eqref{eq:filter-entropy-order} and
\begin{equation}\label{eq:finite-filtering-moments}
\begin{split}
 \frac1P\sum_{x\in\mathbb Z/P\mathbb Z}
       M(x)^2 2^{8.5(\Delta-u(x))}&<2^{0.5169},\\
 \frac1P\sum_{x\in\mathbb Z/P\mathbb Z}
       M(x)^2 2^{8.3(a v(x)-u(x))}&<2^{0.5169}.
\end{split}
\end{equation}
There is an absolute bound, independent of $P$, for the absolute values
of $D,A,E,u,v,\log f_*,\log g_*$, and $\log K_x(w)$.
For every fixed positive rational $\rho$, each of these quantities can
be approximated to absolute error at most $\rho$ by one fixed
deterministic rational-arithmetic procedure, in time polynomial in
$\log P$, given the relevant residues and $P$.  This procedure need not
enumerate the $P$ points.
\end{lemma}

\begin{lemma}[Susceptibility calibration]\label{lem:cavity-calibration}
One has \(J_0=O(W^2)\). Therefore
\begin{equation}\label{eq:27}\tag{27}
                         \mathcal L(P,a)=o(x^2p_0)
\end{equation}
for admissible tests along moving targets with \(D_i=o(x)\),
and uniformly
\[
 |\mathcal L(P,a)|\le Cx^2p_0\{\eta_n+(D_i/x)^\vartheta\}.
\]
\end{lemma}

\begin{lemma}[Existence and the optimized envelope]\label{comp:envelope}
For all sufficiently large $n$, the class \eqref{eq:5} is nonempty and
compact in the uniform topology of inverse quantiles.  The minimum in
\eqref{eq:6} is attained.  For an admissible sweep, $\mathcal M_\lambda$
is locally Lipschitz and nondecreasing in $\lambda$, equals the endpoint
pressure at $\lambda=0$, and is an upper bound for that pressure.
At almost every positive strength its upper derivative per unit
$\log\lambda$ is bounded, at any minimizer at that strength, by
\begin{equation}
 \frac14\int_{u_0}^1 e(r(u))
           \bigl[D_u^2+(S_u-r(u))^2\bigr]\,du.
 \tag{7}\label{eq:7}
\end{equation}
All moments in this formula are for the changed clocks in
\eqref{eq:6}.
\end{lemma}

\begin{lemma}[Contact, cap, and floor]\label{comp:geometry}
At a minimizer there is a continuous absolutely continuous potential
$H$ such that $H'=JG$ for a strictly positive factor $J$,
$\alpha'=M(\alpha)$ on $\{H<0\}$, and $\alpha'=k$ on $\{H>0\}$.
On a band where $\alpha+u_*$ varies by a bounded factor, $J$ has bounded
distortion after normalization at one endpoint.  On the contact set
$\{H=0\}$, almost everywhere,
\begin{equation}
 G=0,\qquad S'\lesssim n^{o(1)},\qquad S\le r.
 \tag{9}\label{eq:9}
\end{equation}
On an open cap component $\{H<0\}$ of radius length $\ell$,
\begin{equation}
 \begin{gathered}
 \Delta S\lesssim n^{o(1)}
        (\ell+r_{\min}\mathbf1_{\mathrm{initial}}),
 \qquad S\le r+\ell,\\
 |S-r|^2\lesssim n^{o(1)}
   \left[D^2+\ell^2+r_{\min}^2\mathbf1_{\mathrm{initial}}\right].
 \end{gathered}
 \tag{10}\label{eq:10}
\end{equation}
Here $\Delta S$ is the increase through the interior of the component.
On contact, $(S-r)^2\lesssim D^2$.  Every cap has
$\ell\lesssim n^{-\delta}L\log n$; if it is contained in a comparable
mass band $u\asymp v\gg u_*$, then
$v\ell\lesssim n^{-\delta}E/d^3$.  A noninitial cap on which $p=0$
throughout satisfies $|S-r|\le\ell$.  The total floor mass is at most
$n^{-\delta}u_*$.
\end{lemma}

\begin{proposition}[Raw moments]\label{comp:raw-moments}
For every fixed $p\ge2$, throughout the path, including masses below
the working interval,
\begin{equation}
 \|X_u\|_p\lesssim_p\sqrt{u+x},\qquad
 \|R_{\mathrm{split\ at}\ u}\|_p\lesssim_p u+x.
 \tag{12}\label{eq:12}
\end{equation}
The bounds also hold at intermediate clock revelations, with their
specified mass.  The norm of a random vector is its Euclidean norm
inside the $L^p$ norm.
\end{proposition}

\begin{lemma}[Projection after a field-clock interval]\label{comp:projection}
Let $V$ be a vector determined by outside branches and by data at or
before their fork with a branch $b$.  Conditional on this data, the
future of $b$ has its usual planted law.  Suppose a field-clock interval
after the fork has length $D_h$, with mass at least $v_->0$ throughout.
For even fixed $p\ge2$, the part of $V\cdot y_b$ left after projection
at the end of the interval satisfies
\begin{equation}
 \|V\cdot(y_b-X_{b,\mathrm{end}})\|_p
 \le C_p(\log n)^2\frac{\|V\|_p}{v_-\sqrt{nD_h}}.
 \tag{13}\label{eq:13}
\end{equation}
Here the masses and clock lengths used in the estimate are bounded
below by inverse powers of $n$.  Differences of two later projections
satisfy the same estimate up to a constant.
\end{lemma}

\begin{lemma}[Postprojection changes]\label{comp:resampling}
Suppose two leaves share only through a mass at most a fixed multiple
of $x_1$, where $x_1\ge x$.  If a projection or resampling is made after
a regular radius $v\ge Cx_1$, with comparable intervals fitting after
the fork and before that projection, the change in their inner product
caused by changing one endpoint has norm
\begin{equation}
 \frac{C_p(\log n)^C}{\sqrt{ne(v)v^2}}
 \tag{16}\label{eq:16}
\end{equation}
in every fixed $L^p$.  For an already projected anchor of norm
$O_p(\sqrt{x_1})$, the bound gains a factor $\sqrt{x_1/v}$.
\end{lemma}

\begin{lemma}[Good split]\label{comp:good-split}
Suppose a regular band of mass and radius of order $v\ge Cx$ contains
a mass interval of length comparable to $v$ on which $S\asymp v$.
There are constants $c_1,c_2>0$, independent of each fixed moment order,
and a deterministic window of mass length $n^{-c_1}v$ with the following
properties.  Its fixed-factor enlargement has $S$ oscillation at most
$n^{-c_1/2}v$, and for every deterministic split in a fixed central
fraction of the window,
\begin{equation}
 \|R_*-S_*\|_p\le C_p n^{-c_2}v
 \tag{17}\label{eq:17}
\end{equation}
for all fixed $p\ge2$.  The window may be selected before the moment
orders or any later fixed recursion depth are chosen.  The constant
$c_1$ may be any sufficiently small positive constant.
\end{lemma}

\begin{lemma}[Trace bounds on sampling units]\label{comp:unit-trace}
Consider a group at comparable masses $u\asymp v$ of total mass at
most $Cv$, and suppose the radii and the raw overlap moments in that
group are bounded at scale $y_0$.  Away from the floor, take as units
complete cap components with comparable endpoint masses, and mass
elements of the contact set.  Let $e_g$ be a lower bound on $e$ in
the group.  If a cap has no initial-wall loss, then within each unit
\begin{equation}
 \operatorname{avg}_{\mathrm{unit}}
       \mathbb E\operatorname{tr}H_u^2
 \lesssim\frac{n^{o(1)}}{ne_g}.
 \tag{20}\label{eq:20}
\end{equation}
On contact this holds pointwise almost everywhere.  In particular the
unit averages of $\mathbb E\operatorname{tr}C_u^2$ and $\mathbb EW_u$
are at most $n^{o(1)}/(ne_gv^2)$ and $n^{o(1)}/(ne_gv)$, respectively.
\end{lemma}

\begin{lemma}[Suppression of the low-group mean]\label{fl:low-mean}
For every minimizing changed path in Lemma~\ref{fl:wall-profile},
uniformly over its low-group splits,
\begin{equation}
 S_u=\frac{K_u}{T}+O(d^3),\qquad
 S_u\le\frac{C d^3}{\varepsilon}=:a_L,
 \qquad K_u=h_u+b_uS_u,\quad 0\le u<s.
 \tag{31}\label{eq:31}
\end{equation}
The constants are uniform in the wall parameters.
\end{lemma}

\begin{proposition}[A positive Laplace window]\label{fl:laplace-window}
For every fixed $T>1$ and $0<m<1/300$, there exist $c_{T,m}>0$,
$C_{T,m}<\infty$, and $n_0(T,m)$ such that
\[
 c_{T,m}n^{20m}\le
 \log\mathbb E\exp\{s(F_n^c-\mathbb EF_n^c)\}
 \le C_{T,m}n^{100m},\qquad s=n^{-1/6+5m},
\]
for all $n\ge n_0(T,m)$.
\end{proposition}

\begin{lemma}[Log-concave augmentation]\label{fl:augmentation}
Let $\mathcal E$ be an independent exponential variable of rate one.
Then $G_n=F_n^c+\mathcal E$ has a log-concave density.  For $0\le t<1$,
\[
 \log\mathbb E e^{t(G_n-\mathbb EG_n)}
       =K_n(t)-t-\log(1-t),\qquad
 \operatorname{Var}G_n=\operatorname{Var}F_n^c+1.
\]
\end{lemma}

\begin{lemma}[Pinned moments for one planted path]\label{lem:found-moments}
At zero normalized spin source and with no other deterministic external
field, the last two lines of \eqref{eq:1} hold with $c_2=1$ and
$c_p\leq1+p^2/3$. All these moments concern one planted path and its
terminal spin, with the full, unconditioned prefix law.
\end{lemma}

\begin{proposition}[Covariance differentiation]\label{prop:found-replica}
Let $K_\theta(u;\sigma,\tau)$ be an affine family of cumulative Gaussian
covariance kernels of a finite hierarchy. Assume that the independent
increment covariances are positive semidefinite throughout the parameter
interval. Let $V=\partial_\theta K_\theta$ and let $P$ be a fixed bounded
spin test on a fixed observed split tree. Then
\begin{equation}
 \frac{d}{d\theta}\nu_\theta[P]
      =\frac12\sum_{c,d}\nu_\theta[P V_{cd}].
 \tag{2}\label{eq:2}
\end{equation}
The signed sum includes coincidences with old labels and between $c,d$.
For distinct labels, $V_{cd}$ is evaluated at their common revelation;
on the diagonal it is evaluated at the terminal covariance. The exact
weights are the real-power weights described in the proof. A constant
diagonal contribution, independent of the summation label, sums to zero.
Conditional means in $P$ can be represented by independent additional
replicas at their specified prefixes before this formula is applied.
\end{proposition}

\begin{theorem}[Rigidity at a small test scale]\label{prof:direct-profile}
Under the preceding hypotheses, every sequence has a subsequence on
which, for some $\kappa$,
\begin{equation}
 \frac{r(xv)}{x}\longrightarrow\frac{v}{\kappa}
 \quad\text{locally uniformly for }v\in(0,\infty),
 \qquad 0<c\le\kappa\le C<\infty.
 \tag{28}\label{eq:28}
\end{equation}
The bounds on $\kappa$ depend only on $T$ and the total-clock bounds.
The same conclusion holds for a comparison with an omitted lower group,
provided its changed paths and the constrained competitors used in the
first variation are admissible.
\end{theorem}

\begin{lemma}[Scalar compactness at the test scale]
\label{prof:scalar-compactness}
Under the hypotheses of Theorem~\ref{prof:direct-profile}, pass to a
subsequence. There is a locally finite measure $\nu$ on $[0,\infty)$,
with cumulative function $U(t)=\nu([0,t])$, such that the rescaled
distributions of $r$ and of $K/T$ both converge locally weakly to $\nu$.
For sufficiently large $t$, $U(t)$ is bounded above and below by fixed
positive multiples of $t$. Further subselection gives
\begin{equation}
 \begin{gathered}
 g_n(t)=\frac{\Gamma_n(Txt)-xt}{x^3}
       \longrightarrow g(t)\quad\text{in }C^1_{\mathrm{loc}}([0,\infty)),
 \\
 g(0)=0,\qquad g''(t)=At-BU(t)\quad\text{for almost every }t,
 \qquad A,B>0.
 \end{gathered}
 \tag{29}\label{eq:29}
\end{equation}
The function $g$ vanishes on $\operatorname{supp}\nu$. The constants
$A,B$ have positive lower bounds and finite upper bounds depending
only on $T$ and the total-clock bound.
\end{lemma}

\begin{theorem}[Moment convergence at the fluctuation scale]\label{thm:moments}
For each fixed $\beta>1$, there are real numbers $a_k=a_k(\beta)$, $k\ge1$, with the following property. For every integer $k\ge1$, there are constants $c_k>0$ and $C_k<\infty$ such that
\begin{equation}\label{eq:moment-rate}
 \big|\mathbb E Y_n^k-a_k\big|\le C_k n^{-c_k},\qquad n\ge2.
\end{equation}
There are also constants $c>0$ and $C<\infty$, depending on $\beta$, for which
\begin{equation}\label{eq:exponential-moments}
 \sup_{n\ge2}\mathbb E e^{c|Y_n|}\le C.
\end{equation}
The limits satisfy $a_1=0$ and $0<a_2<\infty$.
\end{theorem}

\begin{corollary}[Upper disorder-chaos scales in zero-field SK]
\label{cor:disorder-chaos}
Fix $\beta>1$ and $n\ge2$. Put $E_n=\{(i,j):1\le i<j\le n\}$ and
$M=|E_n|=n(n-1)/2$, and let $g'$ be an independent copy of
$g=(g_{ij})_{(i,j)\in E_n}$ in \eqref{eq:model}. Write
$\langle\cdot\rangle_{g,h}$ for expectation under the product of that
model's Gibbs laws with disorders $g,h$, and
$R=n^{-1}\sum_i\sigma_i\tau_i$ for the overlap. Thus the replicas are
independent conditional on their disorders; $\mathbb E$ below also
averages the disorder and any replacement set.

For $t>0$, set $g^t=e^{-t}g+\sqrt{1-e^{-2t}}\,g'$. For an integer
$0\le k\le M$, let $A$ be independent of $g,g'$ and uniform over the
$k$-element subsets of $E_n$. Set $g^A_{ij}=g'_{ij}$ on $A$ and
$g^A_{ij}=g_{ij}$ otherwise. Then
\begin{align}
 \mathbb E\langle R^2\rangle_{g,g^t}
 &\le \frac1n+\frac{2\Var F_n(\beta)}
                 {\beta^2n(1-e^{-t})},\label{eq:chaos-ou}\\
 \mathbb E\langle R^2\rangle_{g,g^A}
 &\le \frac1n+\frac{2(M+1)\Var F_n(\beta)}
                 {\beta^2n(k+1)}+C_\beta n^{-1/2},\label{eq:chaos-replacement}
\end{align}
for a finite constant $C_\beta$ depending only on $\beta$. As $n\to\infty$, for
$t_n\ge0$ and integers $0\le k_n\le M$, these bounds imply
\[
 \begin{aligned}
 t_n n^{2/3}\to\infty
 &\quad\Longrightarrow\quad
 \mathbb E\langle R^2\rangle_{g,g^{t_n}}\to0,\\
 (k_n/M)n^{2/3}\to\infty
 &\quad\Longrightarrow\quad
 \mathbb E\langle R^2\rangle_{g,g^{A_n}}\to0,
 \end{aligned}
\]
where $A_n$ has size $k_n$ as above.
\end{corollary}

\begin{lemma}[Finite cavity quotient]
\label{found:cavity-quotient}
For overlap-polynomial \(P\) invariant as after \eqref{eq:A4}, on any fixed finite-label tree including \(ij\), one has through order \(k-1\)
\[
 \nu[P Q^*_{ij}]=\nu[P(N_{ij,K}/\Psi_K)_{<k}]
          +{\rm Rem}_k+O(m^{-1}),                                      \tag{A7}\label{eq:A7}
\]
where \({\rm Rem}_k\) has at least \(k\) insertions \(J\), times \(P\).
\end{lemma}

\begin{lemma}[Finite increments in the number of sites]
\label{found:size-increment}
At fixed clocks and \(s\), assume that \(bq^2\) is nondecreasing. For every fixed positive integer \(j\), the change from \(m\psi_m\) to \((m+j)\psi_{m+j}\), expanded through total order \(k\), is a polynomial in \(j\) of degree at most \(k\) with zero constant term. Its linear coefficient is the difference of the per-root expectations of \eqref{eq:A6}, with \(\log\Psi\) truncated after degree \(k\). The remainder has the total-pressure bounds given below.
\end{lemma}

\begin{lemma}[Regular scalar profile and a strict top plateau]
\label{paths:base-profile}
At fixed \(T>1\), the scalar minimizing distribution has support \([0,\xi_*]\), satisfies \(\Gamma_0(\xi)=\xi/T\) there, and has a positive initial density. Its active-side distribution function has bounded one-sided derivatives of every fixed order. Moreover \(p_{\rm top}=A_0(\xi_*-)\) belongs to \((0,1)\).
\end{lemma}

\begin{lemma}[Stencil and neighboring-site errors]\label{red:lem-site-smoothing}
For any sequence \(Z_m\), supported or restricted to the relevant
neighborhood of the center,
\[
 \frac{d}{dn}\sum_m w_m(n)Z_m
 =\sum_m w_m(n)\sum_{j=0}^r c_j Z_{m+j}
       +O_r\!\left(D^{-r-1}\sup_m|Z_m|\right).
\]
At the same clock data, uniformly along the paths under consideration,
\begin{equation}\label{red:eq-neighbor}
 |\mathcal K_{m+1}(s)-\mathcal K_m(s)|\le Cs(1+M).
\end{equation}
\end{lemma}

\begin{proposition}[Pair inverse with absolute attachment domination]
\label{inv:pair-inverse}
The kernel \eqref{eq:A8} is considered on extensions of any \emph{fixed} finite list of old labels. A pair function \(u_{ab}\) may depend on the topology with those labels but ignores any unused extra labels (is pulled back by restriction). Indices in this section used as pair arguments are distinct leaves. Normalize terminal mass to 1; other bounded terminal masses reduce to this by mass rescaling, scaling cumulative covariances by the square of the mass. Take a monotone step scalar path \(K\), nonnegative bounded-variation step multiplier \(b\), and retain pair levels in a terminal interval of the hierarchy (the whole interval is allowed). Suppose at these levels
\[
 1-b_r\mathbf E\chi_r^2\ge e>0,\qquad \chi_r=V_{zz}(K_r,Z_{K_r}).
\]
Bounds called polynomial in this section are in \(1+K_{\rm top}+\|b\|_\infty+\operatorname{var}b+e^{-1}\), independent of the number of steps. On the retained levels
\[
 u_{ab}\ \longmapsto\ u_{ab}-\sum_{cd\ {\rm retained}}{\bf M}_{ab,cd} b_{cd}u_{cd}
                                                                     \tag{H1}\label{eq:H1}
\]
has an inverse on each finite step resolution. Each output is an integral of inputs over allocations of up to two more labels (some arguments can also be reused), with weights dominated by a polynomial times the ordinary \emph{absolute} unrestricted attachment rules to the old tree including \(ab\). Restrictions and bounded weights can depend on the topology. This formulation in particular controls new split densities, allowing coincidences and ties to existing forks. It applies with \(ab\) using old labels too. We only need symmetric arrays (on antisymmetric ones the subtracted sum is zero).

\end{proposition}

\begin{lemma}[Residual blocks and integrated increments]
\label{global:residual-blocks}
Fix a positive path law with terminal mass \(a\in[1,4]\), and
parametrize a deterministic increasing family of revealed cuts by \(s\). At a cut \(s\), let branches \(\mathsf a,\mathsf b\)
be conditionally independent continuations with their normalized positive
kernels, given the common prefix. Partition their futures into the same
\(k\) deterministic blocks, the last ending at the terminal spin.
Write \(\Delta_j\) for the martingale increments, so that
\(y-X_s=\sum_{j=1}^k\Delta_j\), and let \(\mu'_j\le a\)
be the largest mass in block \(j\). Evaluating \(W_s\) on branch
\(\mathsf a\), we have
\begin{equation}
 W_s\le k\sum_{i,j}\mu'_j\,
    \mathbf E_{\mathsf b}[(\Delta_i^{\mathsf a}\cdot\Delta_j^{\mathsf b})^2\mid\mathsf a].
 \label{eq:global-block-decomposition}
\end{equation}
Conditioning on \(\mathsf a\) retains its whole branch and the common prefix;
only continuation \(\mathsf b\) is averaged. For any deterministic interval
\(J\), any increment length \(l>0\), and \(q\ge1\), provided all
indicated cuts exist, put \(s_-=\inf J\) and \(s_+=\sup J+2l\). Then
\begin{equation}
 \left\|\int_J|X_{s+2l}-X_{s+l}|^2ds\right\|_q
       \le C_q l\,\bigl\||X_{s_+}-X_{s_-}|^2\bigr\|_q .
 \label{eq:global-grid}
\end{equation}
The same estimate holds with increment \(X_{s+l}-X_s\).
For any nonnegative process \(V_s\), not necessarily adapted,
\begin{equation}
 \left\|\int\mathbf E_sV_s\,ds\right\|_q
       \le C_q\left\|\int V_s\,ds\right\|_q .
 \label{eq:global-dual-doob}
\end{equation}
\end{lemma}

\begin{proposition}[Uniform weighted comparison budgets]\label{bud:targets}

The averaging bounds needed are, on all segments of Proposition~\ref{prop:increment}, uniformly,
\[
 \mathbf E_\gamma\left[\max_{U\lesssim u\lesssim1}
       u\int_{v\asymp u} A_v\,dv\right]\lesssim_\circ U^4,              \tag{C1}\label{eq:C1}
\]
where one can use ordinary dyads with fixed comparable enlargements, and on size paths in addition
\[
 \int (v^2+U^2)\mathbf E_\gamma A_v\,dv \le x^{4+c},\qquad
 f_{\rm spin}(K)+\int (K-h)^2/(4b)- f_m^0 \le x^{4+c}.                  \tag{C2}\label{eq:C2}
\]
The second assertion of \eqref{eq:C2} is pointwise, with some \(c>0\) independent of sufficiently small \(p_*\).

\end{proposition}

\begin{proposition}[Comparability and the calibrated initial slope]\label{bud:coarse-profile}
For every optimizer in \eqref{eq:C5}, uniformly,
\[
 r(v)\asymp v\ (w_c\le v\le1),\qquad
 \sup_{c u\le v\le C u}|r(v)-q(v)|=o(u)                                 \tag{C7}\label{eq:C7}
\]
for each fixed \(0<c<C\) (fixed numeric multiples, not the removal profile). \end{proposition}

\begin{lemma}[Second moments with an enhanced floor]\label{bud:outer-second}
Under the same outer-regularity hypotheses, on regular mass dyads, with
$B_f=X^{3/2}\lambda^{s_0/2}\Lambda^{-5/12}$,
\[
 (\operatorname{avg}D^2)^{1/2}
 \lesssim_\circ (x^6/(C(v)v))^{1/3}+x^3/(v\sqrt{C(v)})
            +m^{\delta/2}v_*+{\bf1}_{v\asymp u}\,u B_f .               \tag{C10}\label{eq:C10}
\]
The average is normalized by the length of the mass dyad. The indicator
denotes a fixed band covering the enhanced floor, when present. The
constants are uniform over optimizers with the stated outer bounds.
\end{lemma}

\begin{proposition}[Closure for the modified constraints]\label{bud:modified-closure}
Along any fixed sequence of optimizers with the strong-removal hypotheses
above and fixed outer-comparability constants, the following estimate holds
for targets \(i\) with
\(cw\le v_i\le Cw\) and \(r_i\le Cw\),
\begin{equation}\label{eq:bud-coarse-closure}
 \frac{|S_i-\Gamma_{\widehat K}(\widehat K_i)|}{w^3}
 \le C'\{\varepsilon_m+(D_i/w)^\vartheta\},
 \qquad \varepsilon_m\longrightarrow0,\quad\vartheta>0.
\end{equation}
The constants and modulus are common to the fixed target band. Thus
this difference is \(O(w^3)\) throughout the band, and is
\(o(w^3)\) along any moving target with \(D_i=o(w)\).
Since the target-band integrals of \(D^2\) are \(o(w^3)\), the same
modulus gives, separately in the two coordinates,
\begin{equation}\label{eq:bud-coarse-closure-integrals}
 \frac1w\int
 \frac{|S_i-\Gamma_{\widehat K}(\widehat K_i)|}{w^3}\,dv_i=o(1),
 \qquad
 \frac1w\int
 \frac{|S_{\alpha(r)}-\Gamma_{\widehat K}(\widehat K_{\alpha(r)})|}
      {w^3}\,dr=o(1).
\end{equation}
Each integral is restricted to the target band just described.
\end{proposition}

\begin{lemma}[Finite strengthening]\label{bud:strengthening}
On a slightly smaller interval interior to \(I_j\), at each stage,
